def _action_1(core):
    """arm starts as we set off"""
    if core.leftTask is not None:
        core.leftTask.run(500)


def _action_2(core):
    """arm down, robot waits"""
    if core.leftTask is not None:
        core.leftTask.run_angle(500, 90, wait=True)


def _action_3(core):
    """arm up, robot waits"""
    if core.leftTask is not None:
        core.leftTask.run_angle(500, -90, wait=True)


def run(core):
    """Drive this run. The only thing runs.py needs to call."""
    trajectory = Trajectory.fromValues(STEPS, MARKERS, COUNT, DATA)

    # bound in the order they FIRE, which is not necessarily
    # the order the steps were written
    trajectory.withMarkers((
        lambda: _action_1(core),
        lambda: _action_2(core),
        lambda: _action_3(core),
    ))

    trajectory.follow(core)
